CREATE SCHEMA IF NOT EXISTS "exam";

CREATE TABLE "exam"."exam_categories" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "name" VARCHAR(150) NOT NULL, "slug" VARCHAR(180) NOT NULL, "description" TEXT, "display_order" INTEGER NOT NULL DEFAULT 0, "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', "archived_at" TIMESTAMPTZ, "version" INTEGER NOT NULL DEFAULT 1, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_categories_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."exam_groups" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "category_id" UUID, "name" VARCHAR(150) NOT NULL, "slug" VARCHAR(180) NOT NULL, "description" TEXT, "display_order" INTEGER NOT NULL DEFAULT 0, "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', "archived_at" TIMESTAMPTZ, "version" INTEGER NOT NULL DEFAULT 1, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_groups_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."states" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "name" VARCHAR(100) NOT NULL, "code" VARCHAR(10) NOT NULL, "slug" VARCHAR(120) NOT NULL, "state_type" VARCHAR(20) NOT NULL, "display_order" INTEGER NOT NULL DEFAULT 0, "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', CONSTRAINT "states_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."exam_bodies" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "name" VARCHAR(200) NOT NULL, "short_name" VARCHAR(80), "slug" VARCHAR(180) NOT NULL, "description" TEXT, "official_website" TEXT, "logo_media_id" UUID, "status" VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', "version" INTEGER NOT NULL DEFAULT 1, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_bodies_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."exams" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "name" VARCHAR(250) NOT NULL, "short_name" VARCHAR(100), "slug" VARCHAR(200) NOT NULL, "description" TEXT, "exam_body_id" UUID NOT NULL, "exam_scope" VARCHAR(30) NOT NULL, "exam_mode" VARCHAR(30), "official_website" TEXT, "logo_media_id" UUID, "is_featured" BOOLEAN NOT NULL DEFAULT false, "display_order" INTEGER NOT NULL DEFAULT 0, "status" VARCHAR(20) NOT NULL DEFAULT 'DRAFT', "archived_at" TIMESTAMPTZ, "version" INTEGER NOT NULL DEFAULT 1, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exams_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."exam_category_mappings" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "exam_id" UUID NOT NULL, "category_id" UUID NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_category_mappings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."exam_group_mappings" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "exam_id" UUID NOT NULL, "group_id" UUID NOT NULL, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_group_mappings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."exam_state_mappings" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "exam_id" UUID NOT NULL, "state_id" UUID NOT NULL, "is_primary" BOOLEAN NOT NULL DEFAULT false, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_state_mappings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."exam_aliases" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "exam_id" UUID NOT NULL, "alias" VARCHAR(200) NOT NULL, "normalized_alias" VARCHAR(200) NOT NULL, "language_code" VARCHAR(10) NOT NULL DEFAULT 'en', "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_aliases_pkey" PRIMARY KEY ("id"));
CREATE TABLE "exam"."exam_cycles" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "exam_id" UUID NOT NULL, "cycle_year" SMALLINT NOT NULL, "cycle_code" VARCHAR(60) NOT NULL, "cycle_label" VARCHAR(100) NOT NULL, "vacancy_count" INTEGER, "notification_reference" VARCHAR(200), "cycle_status" VARCHAR(30) NOT NULL DEFAULT 'UPCOMING', "publication_status" VARCHAR(30) NOT NULL DEFAULT 'DRAFT', "archived_at" TIMESTAMPTZ, "version" INTEGER NOT NULL DEFAULT 1, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "exam_cycles_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "exam_categories_name_key" ON "exam"."exam_categories"("name"); CREATE UNIQUE INDEX "exam_categories_slug_key" ON "exam"."exam_categories"("slug"); CREATE UNIQUE INDEX "exam_groups_name_key" ON "exam"."exam_groups"("name"); CREATE UNIQUE INDEX "exam_groups_slug_key" ON "exam"."exam_groups"("slug"); CREATE UNIQUE INDEX "states_code_key" ON "exam"."states"("code"); CREATE UNIQUE INDEX "states_slug_key" ON "exam"."states"("slug"); CREATE UNIQUE INDEX "exam_bodies_name_key" ON "exam"."exam_bodies"("name"); CREATE UNIQUE INDEX "exam_bodies_slug_key" ON "exam"."exam_bodies"("slug"); CREATE UNIQUE INDEX "exams_slug_key" ON "exam"."exams"("slug"); CREATE UNIQUE INDEX "exam_category_mappings_exam_id_category_id_key" ON "exam"."exam_category_mappings"("exam_id", "category_id"); CREATE UNIQUE INDEX "exam_group_mappings_exam_id_group_id_key" ON "exam"."exam_group_mappings"("exam_id", "group_id"); CREATE UNIQUE INDEX "exam_state_mappings_exam_id_state_id_key" ON "exam"."exam_state_mappings"("exam_id", "state_id"); CREATE UNIQUE INDEX "exam_aliases_normalized_alias_language_code_key" ON "exam"."exam_aliases"("normalized_alias", "language_code"); CREATE UNIQUE INDEX "exam_cycles_exam_id_cycle_code_key" ON "exam"."exam_cycles"("exam_id", "cycle_code");
CREATE INDEX "exam_groups_category_id_idx" ON "exam"."exam_groups"("category_id"); CREATE INDEX "exams_body_id_idx" ON "exam"."exams"("exam_body_id"); CREATE INDEX "exams_status_display_order_idx" ON "exam"."exams"("status", "display_order"); CREATE INDEX "exam_aliases_exam_id_idx" ON "exam"."exam_aliases"("exam_id"); CREATE INDEX "exam_cycles_exam_id_cycle_year_idx" ON "exam"."exam_cycles"("exam_id", "cycle_year"); CREATE INDEX "exam_cycles_publication_status_cycle_status_idx" ON "exam"."exam_cycles"("publication_status", "cycle_status");
ALTER TABLE "exam"."exam_groups" ADD CONSTRAINT "exam_groups_category_id_fkey" FOREIGN KEY ("category_id") REFERENCES "exam"."exam_categories"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exams" ADD CONSTRAINT "exams_exam_body_id_fkey" FOREIGN KEY ("exam_body_id") REFERENCES "exam"."exam_bodies"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exam_category_mappings" ADD CONSTRAINT "exam_category_mappings_exam_id_fkey" FOREIGN KEY ("exam_id") REFERENCES "exam"."exams"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exam_category_mappings" ADD CONSTRAINT "exam_category_mappings_category_id_fkey" FOREIGN KEY ("category_id") REFERENCES "exam"."exam_categories"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exam_group_mappings" ADD CONSTRAINT "exam_group_mappings_exam_id_fkey" FOREIGN KEY ("exam_id") REFERENCES "exam"."exams"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exam_group_mappings" ADD CONSTRAINT "exam_group_mappings_group_id_fkey" FOREIGN KEY ("group_id") REFERENCES "exam"."exam_groups"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exam_state_mappings" ADD CONSTRAINT "exam_state_mappings_exam_id_fkey" FOREIGN KEY ("exam_id") REFERENCES "exam"."exams"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exam_state_mappings" ADD CONSTRAINT "exam_state_mappings_state_id_fkey" FOREIGN KEY ("state_id") REFERENCES "exam"."states"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exam_aliases" ADD CONSTRAINT "exam_aliases_exam_id_fkey" FOREIGN KEY ("exam_id") REFERENCES "exam"."exams"("id") ON DELETE RESTRICT; ALTER TABLE "exam"."exam_cycles" ADD CONSTRAINT "exam_cycles_exam_id_fkey" FOREIGN KEY ("exam_id") REFERENCES "exam"."exams"("id") ON DELETE RESTRICT;

